  .log { margin-top:12px; font-family:ui-monospace,Menlo,Consolas,monospace; font-size:.8rem; color:var(--muted); max-height:150px; overflow:auto; white-space:pre-wrap; }
  .fallback { margin-top:20px; padding:12px; border-left:3px solid var(--line); color:var(--muted); font-size:.8rem; }
