<body>
<h1>二分查找单步演示</h1>
<p class="sub">复用 binary-search.v1：升序整数数组，支持命中、未命中、空数组与键盘操作。</p>

<div class="panel">
  <div class="row">
    <div>
      <label for="values">升序数组（逗号分隔，最多 32 个整数）</label>
      <input id="values" type="text" value="1,3,5,7,9,11,13" autocomplete="off" spellcheck="false">
    </div>
    <div>
      <label for="target">目标值</label>
      <input id="target" type="text" value="7" autocomplete="off" spellcheck="false">
    </div>
  </div>
  <div class="btns">
    <button id="apply" class="primary" type="button">应用参数</button>
    <button id="step" type="button">单步 (S)</button>
    <button id="reset" type="button">重置 (R)</button>
  </div>
  <p class="hint">键盘：按 <b>S</b> 单步，按 <b>R</b> 重置（输入框聚焦时除外）。</p>
</div>

<div class="panel">
  <div id="cells" class="cells"></div>
  <div id="result">尚未开始。点击“应用参数”后按“单步”。</div>
  <div id="log" class="log"></div>
</div>

<p class="fallback">本任务用于公开合成资源流程评测，不代表真实学习者数据。若脚本不可用，请按文本说明操作：输入升序数组与目标值，反复点击“单步”缩小查找区间，直到命中或区间为空。</p>

<script>
(function () {
  "use strict";

  var MAX_LEN = 32;
  var MIN_V = -1000000;
  var MAX_V = 1000000;

  var elValues = document.getElementById("values");
  var elTarget = document.getElementById("target");
  var elApply = document.getElementById("apply");
  var elStep = document.getElementById("step");
  var elReset = document.getElementById("reset");
  var elCells = document.getElementById("cells");
  var elResult = document.getElementById("result");
  var elLog = document.getElementById("log");

  var state = null;

  function parseValues(raw) {
    var parts = String(raw).split(/[,，\s]+/);
    var out = [];
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i].trim();
      if (p === "") continue;
      if (!/^-?\d+$/.test(p)) return { error: "数组包含非整数项：" + p };
      var n = parseInt(p, 10);
      if (n < MIN_V || n > MAX_V) return { error: "数值超出范围 [-1000000, 1000000]：" + p };
      out.push(n);
    }
    if (out.length > MAX_LEN) return { error: "数组最多 " + MAX_LEN + " 个元素。" };
    for (var j = 1; j < out.length; j++) {
      if (out[j] < out[j - 1]) return { error: "数组必须升序排列。" };
    }
    return { values: out };
  }

  function parseTarget(raw) {
    var p = String(raw).trim();
    if (!/^-?\d+$/.test(p)) return { error: "目标值必须是整数。" };
    var n = parseInt(p, 10);
    if (n < MIN_V || n > MAX_V) return { error: "目标值超出范围 [-1000000, 1000000]。" };
    return { target: n };
  }

  function setResult(text, cls) {
    elResult.textContent = text;
    elResult.className = cls || "";
  }

  function log(line) {
    elLog.textContent += line + "\n";
    elLog.scrollTop = elLog.scrollHeight;
  }

  function render() {
    elCells.textContent = "";
    if (!state) return;
    var vals = state.values;
    if (vals.length === 0) {
      var note = document.createElement("div");
      note.className = "empty-note";
      note.textContent = "（空数组：没有任何元素可查找）";
      elCells.appendChild(note);
      return;
    }
    for (var i = 0; i < vals.length; i++) {
      var cell = document.createElement("div");
      cell.className = "cell";
      if (state.done) {
        if (state.foundIndex === i) cell.className += " found";
        else cell.className += " dropped";
      } else {
        if (i < state.lo || i > state.hi) cell.className += " dropped";
        else cell.className += " in-range";
        if (i === state.mid) cell.className += " mid";
      }
      var idx = document.createElement("span");
      idx.className = "idx";
      idx.textContent = "[" + i + "]";
      var val = document.createElement("span");
      val.className = "val";
      val.textContent = String(vals[i]);
      cell.appendChild(idx);
      cell.appendChild(val);
      elCells.appendChild(cell);
    }
  }

  function apply() {
    var pv = parseValues(elValues.value);
    if (pv.error) { setResult("参数错误：" + pv.error, "miss"); return; }
    var pt = parseTarget(elTarget.value);
    if (pt.error) { setResult("参数错误：" + pt.error, "miss"); return; }

    state = {
      values: pv.values,
      target: pt.target,
      lo: 0,
      hi: pv.values.length - 1,
      mid: -1,
      done: false,
      foundIndex: -1,
      steps: 0
    };
    elLog.textContent = "";
    log("应用参数：数组长度=" + pv.values.length + "，目标=" + pt.target);

    if (pv.values.length === 0) {
      state.done = true;
      setResult("空数组：未命中（没有元素可比较）。", "empty");
      log("空数组，直接判定未命中。");
    } else {
      setResult("已就绪。点击“单步”开始查找。", "");
    }
    render();
    updateButtons();
  }

  function step() {
    if (!state) { setResult("请先点击“应用参数”。", "miss"); return; }
    if (state.done) { setResult("查找已结束，请点击“重置”或重新应用参数。", ""); return; }
    if (state.lo > state.hi) {
      state.done = true;
      setResult("未命中：查找区间为空，目标 " + state.target + " 不在数组中。", "miss");
      log("区间为空 -> 未命中。");
      render();
      updateButtons();
      return;
    }

    state.steps++;
    var mid = Math.floor((state.lo + state.hi) / 2);
    state.mid = mid;
    var mv = state.values[mid];
    log("第 " + state.steps + " 步：lo=" + state.lo + " hi=" + state.hi + " mid=" + mid + " 值=" + mv);

    if (mv === state.target) {
      state.done = true;
      state.foundIndex = mid;
      setResult("命中：目标 " + state.target + " 位于索引 " + mid + "（共 " + state.steps + " 步）。", "hit");
      log("命中于索引 " + mid + "。");
    } else if (mv < state.target) {
      state.lo = mid + 1;
      setResult("mid 值 " + mv + " < 目标 " + state.target + "，向右半区继续。", "");
    } else {
      state.hi = mid - 1;
      setResult("mid 值 " + mv + " > 目标 " + state.target + "，向左半区继续。", "");
    }

    if (!state.done && state.lo > state.hi) {
      state.done = true;
      setResult("未命中：查找区间为空，目标 " + state.target + " 不在数组中。", "miss");
      log("区间为空 -> 未命中。");
    }

    render();
    updateButtons();
  }

  function reset() {
    if (!state) { setResult("尚未开始。点击“应用参数”后按“单步”。", ""); return; }
    state.lo = 0;
    state.hi = state.values.length - 1;
    state.mid = -1;
    state.done = false;
    state.foundIndex = -1;
    state.steps = 0;
    elLog.textContent = "";
    log("已重置。");
    if (state.values.length === 0) {
      state.done = true;
      setResult("空数组：未命中（没有元素可比较）。", "empty");
    } else {
      setResult("已重置。点击“单步”开始查找。", "");
    }
    render();
    updateButtons();
  }

  function updateButtons() {
    var running = state && !state.done;
    elStep.disabled = !running;
  }

  elApply.addEventListener("click", apply);
  elStep.addEventListener("click", step);
  elReset.addEventListener("click", reset);

  document.addEventListener("keydown", function (e) {
    var t = e.target;
    if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA")) return;
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    var k = e.key ? e.key.toLowerCase() : "";
    if (k === "s") { e.preventDefault(); step(); }
    else if (k === "r") { e.preventDefault(); reset(); }
  });

  apply();
})();
</script>
</body>
